      "content": "{\n  \"name\": \"dsh-cliworker-now\",\n  \"version\": \"0.8.9\",\n  \"private\": true,\n  \"description\": \"Multiple agent CLI conversations in the DeepSeek Harness sidebar\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=22.19.0\"\n  },\n  \"packageManager\": \"pnpm@11.25.0\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/host/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/host/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./typert\": {\n      \"types\": \"./lib/typert.host.d.ts\",\n      \"default\": \"./lib/typert.host.js\"\n    },\n    \"./remote\": {\n      \"types\": \"./lib/typert.remote-client.d.ts\",\n      \"default\": \"./lib/typert.remote-client.js\"\n    },\n    \"./icon\": \"./icon.png\"\n  },\n  \"files\": [\n    \"lib\",\n    \"runtime-host\",\n    \"!lib/*.tsbuildinfo\",\n    \"cordis.patch.yml\",\n    \"icon.png\",\n    \"README.md\",\n    \"README.en.md\",\n    \"lib/typert.host.js\",\n    \"lib/typert.host.d.ts\",\n    \"lib/typert.remote-client.js\",\n    \"lib/typert.remote-client.d.ts\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\",\n        \"@deepseek-ai/dsh-client-ui-session\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-theme\",\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-workspace\",\n        \"@deepseek-ai/dsh-client-ui-input-trigger\",\n        \"@deepseek-ai/dsh-client-ui-commands\",\n        \"@deepseek-ai/dsh-client-ui-subagent\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"typecheck\": \"node scripts/build.mjs --typecheck-only\",\n    \"build\": \"node scripts/build.mjs\",\n    \"prepack\": \"node scripts/build.mjs\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"test:windows:remote\": \"node scripts/windows-remote.mjs\",\n    \"clean\": \"node scripts/clean.mjs\",\n    \"smoke:real\": \"tsx scripts/smoke-real.ts\",\n    \"smoke:stop\": \"tsx scripts/smoke-stop.ts\",\n    \"build:preview\": \"node scripts/build-preview.mjs\",\n    \"smoke:multi\": \"tsx scripts/smoke-multi.ts\",\n    \"smoke:extended\": \"tsx scripts/smoke-extended.ts\",\n    \"spec\": \"OPENSPEC_TELEMETRY=0 openspec\",\n    \"spec:list\": \"pnpm spec list\",\n    \"spec:check\": \"pnpm spec validate --all --strict --no-interactive\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.4 || 4.0.5 || ~4.1.0\",\n    \"@deepseek-ai/dsh-agent\": \"*\",\n    \"@deepseek-ai/dsh-api-gateway\": \"*\",\n    \"@deepseek-ai/dsh-api-remotes\": \"*\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"*\",\n    \"@deepseek-ai/dsh-brand\": \"*\",\n    \"@deepseek-ai/dsh-client-locale\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"*\",\n    \"@deepseek-ai/dsh-jobs\": \"*\",\n    \"@deepseek-ai/dsh-llm\": \"*\",\n    \"@deepseek-ai/dsh-plan-mode\": \"*\",\n    \"@deepseek-ai/dsh-sandbox\": \"*\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"*\",\n    \"@deepseek-ai/dsh-scope\": \"*\",\n    \"@deepseek-ai/dsh-session\": \"*\",\n    \"@deepseek-ai/dsh-subagent\": \"*\",\n    \"@deepseek-ai/dsh-subprocess\": \"*\",\n    \"@deepseek-ai/dsh-system-prompt\": \"*\",\n    \"@deepseek-ai/dsh-tools\": \"*\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"*\",\n    \"@deepseek-ai/dsh-typert-registry\": \"*\",\n    \"@deepseek-ai/dsh-user-approval\": \"*\",\n    \"@deepseek-ai/dsh-user-questions\": \"*\",\n    \"@deepseek-ai/dsh-util-values\": \"*\",\n    \"@deepseek-ai/dsh-workspace\": \"*\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-commands\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-subagent\": \"*\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@xterm/addon-fit\": \"0.11.0\",\n    \"@xterm/xterm\": \"6.0.0\",\n    \"yaml\": \"2.9.1\",\n    \"zod\": \"4.4.3\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-gateway\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-brand\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-commands\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-jobs\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-plan-mode\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-subagent\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-subprocess-local\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-generator\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-user-questions\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-util-values\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-workspace\": \"0.2.2-rc.1\",\n    \"@fission-ai/openspec\": \"1.14.1\",\n    \"@types/node\": \"22.18.6\",\n    \"@types/react\": \"18.3.28\",\n    \"@types/react-dom\": \"18.3.7\",\n    \"@types/react-test-renderer\": \"18.3.1\",\n    \"immer\": \"^10.2.0\",\n    \"prettier\": \"3.6.2\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"18.3.1\",\n    \"react-test-renderer\": \"18.3.1\",\n    \"tsdown\": \"0.22.2\",\n    \"tsx\": \"4.21.0\",\n    \"typescript\": \"6.0.3\",\n    \"vitest\": \"4.1.8\",\n    \"zustand\": \"~4.4.7\",\n    \"@deepseek-ai/dsh-client-ui-subagent\": \"0.2.2-rc.1\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/SuperWheel/dsh-cliworker-now.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/SuperWheel/dsh-cliworker-now/issues\"\n  },\n  \"homepage\": \"https://github.com/SuperWheel/dsh-cliworker-now#readme\"\n}\n"
